import { test, expect } from '@playwright/test'
import sharp from 'sharp'

import { routes } from './fixtures'

/**
 * What a shared link shows on Facebook, WhatsApp and X:
 *
 * - Exhibition, artist and artwork pages: that page's own main image (the
 *   exhibition cover, the artist's photo, the artwork), whole on white, as a
 *   light 1200 × 630 JPEG generated by the page's opengraph-image route.
 * - Every other page: the monogram card from src/app/opengraph-image.tsx.
 *
 * Light matters: WhatsApp shows no picture at all for heavy images, which is
 * why the stored ~800 KB WebPs are never linked directly.
 */
const OWN_IMAGE_PAGES = [
  ['exhibition', routes.exhibition()],
  ['artist', routes.artistProfile()],
  ['artwork', routes.artwork()],
] as const

async function previewUrls(page: import('@playwright/test').Page, url: string) {
  await page.goto(url)
  const og = await page.locator('meta[property="og:image"]').first().getAttribute('content')
  const twitter = await page.locator('meta[name="twitter:image"]').first().getAttribute('content')
  return { og: og && new URL(og).pathname, twitter: twitter && new URL(twitter).pathname }
}

async function expectLightImage(
  request: import('@playwright/test').APIRequestContext,
  path: string,
  type: 'image/jpeg' | 'image/png',
  size: { width: number; height: number },
) {
  const res = await request.get(path)
  expect(res.ok(), `${path} → ${res.status()}`).toBe(true)
  expect(res.headers()['content-type']).toBe(type)
  const body = await res.body()
  const meta = await sharp(body).metadata()
  expect({ width: meta.width, height: meta.height }).toEqual(size)
  expect(body.length, `${path} is too heavy for WhatsApp`).toBeLessThan(300_000)
}

for (const [kind, url] of OWN_IMAGE_PAGES) {
  test(`the ${kind} page shares its own image`, async ({ page, request }) => {
    const { og, twitter } = await previewUrls(page, url)
    expect(og).toBe(`${new URL(url, 'http://x').pathname}/opengraph-image`)
    expect(twitter).toBe(`${new URL(url, 'http://x').pathname}/twitter-image`)
    await expectLightImage(request, og!, 'image/jpeg', { width: 1200, height: 630 })
  })
}

test('every other page shares the monogram card', async ({ page, request }) => {
  for (const url of ['/', '/prints']) {
    const { og } = await previewUrls(page, url)
    expect(og, url).toBe('/opengraph-image')
  }
  await expectLightImage(request, '/opengraph-image', 'image/png', { width: 1200, height: 630 })
  await expectLightImage(request, '/twitter-image', 'image/png', { width: 1200, height: 600 })
})

test('a page with no image falls back to the monogram card instead of breaking', async ({
  request,
}) => {
  await expectLightImage(request, '/artworks/no-such-artwork-e2e/opengraph-image', 'image/jpeg', {
    width: 1200,
    height: 630,
  })
})

test('the avatar is the logo search engines see and the home-screen icon', async ({
  page,
  request,
}) => {
  await page.goto('/')
  const jsonLd = JSON.parse(
    (await page.locator('script[type="application/ld+json"]').first().textContent()) ?? '{}',
  )
  expect(new URL(jsonLd.logo).pathname).toBe('/avatar.png')
  await expectLightImage(request, '/avatar.png', 'image/png', { width: 1080, height: 1080 })

  const appleIcon = await page.locator('link[rel="apple-touch-icon"]').first().getAttribute('href')
  await expectLightImage(request, appleIcon!, 'image/png', { width: 180, height: 180 })
})
